package taxdelta.general

/** A fixture table, as generated by the build from a CSV under mill-build/resources/fixtures/general.
 *  Values are kept as strings, as in the CSV; the first column is the row key. */
final case class Table( header : IndexedSeq[String], rows : IndexedSeq[IndexedSeq[String]] ):
  require(header.nonEmpty, "A table needs at least one column.")
  require(rows.forall(_.length == header.length), "All rows must have as many values as the header.")

  private lazy val colIndex : Map[String, Int] = header.zipWithIndex.toMap
  private lazy val rowIndex : Map[String, Int] = rows.map(_(0)).zipWithIndex.toMap

  def numRows : Int = rows.length

  def hasColumn( col : String ) : Boolean = colIndex.contains(col)
  def hasRow( key : String ) : Boolean = rowIndex.contains(key)

  def column( col : String ) : Int =
    colIndex.getOrElse(col, throw new NoSuchElementException(s"No column '$col' among ${header.mkString(", ")}"))
  def row( key : String ) : Int =
    rowIndex.getOrElse(key, throw new NoSuchElementException(s"No row '$key'"))

  def string( row : Int, col : String ) : String = rows(row)(column(col))
  def string( key : String, col : String ) : String = string(row(key), col)

  /** A required number; a blank value is an error. */
  def double( row : Int, col : String ) : Double =
    val s = string(row, col).trim
    if s.isEmpty then throw new IllegalStateException(s"Blank value at row $row, column '$col'") else s.toDouble
  def double( key : String, col : String ) : Double = double(row(key), col)

  /** An optional number; a blank value is None. */
  def doubleOption( row : Int, col : String ) : Option[Double] =
    val s = string(row, col).trim
    if s.isEmpty then None else Some(s.toDouble)
  def doubleOption( key : String, col : String ) : Option[Double] = doubleOption(row(key), col)

  def strings( col : String ) : IndexedSeq[String] = rows.indices.map(string(_, col))
  def doubles( col : String ) : IndexedSeq[Double] = rows.indices.map(double(_, col))
